// B-02: each document type chases the person who owns it, on a ladder,
// instead of one daily blob to one shared inbox.
const LADDER = [90, 60, 30, 14, 7, 3, 1];
const OVERDUE_EVERY_N_DAYS = 1;          // once overdue, chase daily
const PORTAL = $('Config').first().json.portal_url;
const DIRECTOR = $('Config').first().json.director_email;

const users = $('Get Users').all().map(u => u.json);
const findUser = (name) => {
  if (!name) return null;
  const k = String(name).trim().toLowerCase();
  return users.find(u =>
    String(u.full_name || '').toLowerCase() === k ||
    String(u.username || '').toLowerCase() === k ||
    String(u.email || '').toLowerCase() === k) || null;
};

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const d = Number(r.days_left);
  const overdue = d < 0;
  const onLadder = LADDER.includes(d);
  if (!overdue && !onLadder) continue;
  if (overdue && (Math.abs(d) % OVERDUE_EVERY_N_DAYS !== 0)) continue;

  const u = findUser(r.owner_name);
  const who = r.owner_name || 'nobody named';
  const url = `${PORTAL}/record/${r.form_code}/${r.id}`;
  const head = overdue
    ? `OVERDUE by ${Math.abs(d)} day(s)`
    : `Expires in ${d} day(s)`;

  const message =
`${head}: ${r.item}

Register  : ${r.form_title} (${r.form_code})
Document  : ${r.doc_no}
Expiry    : ${r.due_date}
Owner     : ${who}
Status    : ${r.status || '-'}

Open the record: ${url}

Renew it and upload the replacement against this record. The reminder stops
by itself once the new expiry date is saved.`;

  out.push({ json: {
    channel: overdue || d <= 7 ? 'email,whatsapp,slack' : 'email',
    to_email: u ? u.email : DIRECTOR,
    to_phone: u ? (u.phone || '') : '',
    subject: `[DHARANI 360] ${head} - ${r.item}`,
    message,
    // passed through for the renewal-task branch
    form_code: r.form_code, record_id: r.id, doc_no: r.doc_no,
    item: r.item, owner_name: r.owner_name, days_left: d,
    due_date: r.due_date, record_url: url,
    open_renewal_task: d === 90 || d === 30,
  }});
}
return out;
